//! 🧪️ Real original Drawing issuance lends every authored vector kind without a scene allocation or payload clone.
use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:64,maximum_copy_bytes:16*1024*1024,maximum_capacity_bytes:16*1024*1024,maximum_release_bytes:16*1024*1024,maximum_depth:256}}
fn text(value:&dyn Utf8Text)->String{let mut output=String::new();for at in 0..value.text_chunk_count(){output.push_str(value.text_chunk(at).unwrap())}output}
#[test]
fn original_native_graph_preserves_all_authored_descriptors_and_never_creates_a_scene(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../✅️validation/🧪️.json")).unwrap();let document:DrawingSnapshot=serde_json::from_value(fixture["base"].clone()).unwrap();let(mut source,_)=RetainedCloneSource::admit_owned(document,(),grant()).unwrap_or_else(|_|panic!("actual original Draw owner"));let original=semio_framework_io_ports::erase_child_admission_source(source.borrow(),0x4348494c);for denied in [Default::default(),RetainedCloneGrant{maximum_copy_bytes:0,..grant()},RetainedCloneGrant{maximum_depth:0,..grant()}]{let step=DRAWING_VECTOR_SOURCE.read(original,denied).unwrap();assert!(!step.done&&step.graph.is_none());assert_eq!(step.progress,Default::default());}let step=DRAWING_VECTOR_SOURCE.read(original,grant()).unwrap();assert_eq!(step.progress.retained_capacity_bytes,0);assert_eq!(step.progress.released_bytes,0);assert!(step.progress.fits(grant()));let graph=step.graph.unwrap();assert_eq!(graph as*const dyn VectorGraphSourceV1 as*const (),source.borrow().get()as*const DrawingSnapshot as*const ());assert_eq!(text(graph.schema()),"drawing.document");assert_eq!(graph.root_count(),5);assert_eq!(graph.asset_count(),1);let asset=graph.asset(0).unwrap();assert_eq!(text(asset.key),"pixel");assert_eq!(asset.samples.sample(0),Some([0,64,128,255]));let mut pending=Vec::new();for at in(0..graph.root_count()).rev(){pending.push(graph.root(at).unwrap());}let mut kinds=Vec::new();while let Some(node)=pending.pop(){let d=node.descriptor();assert_eq!(d.paint.fill_rule(),if text(d.id)=="path"{"evenodd"}else{"nonzero"});match d.content{VectorContentRef::Path(path)=>{kinds.push("path");assert_eq!(path.segment_count(),2);assert!(matches!(path.segment(0),Some(VectorSegment::MoveTo{..})));assert_eq!(d.paint.stop_count(),2);assert_eq!(d.paint.stop(1).unwrap().offset,1.0);assert_eq!(d.paint.dash(1),Some(1.0));},VectorContentRef::Shape(shape)=>{kinds.push("shape");if let Some(VectorShapeRef::Circle{r,..})=shape.primitive(){assert_eq!(r,2.0)}else{panic!("original circle geometry")};},VectorContentRef::Text{content,size,font_family,..}=>{kinds.push("text");assert_eq!(text(content),"Aé🌍");assert_eq!(size,12.0);assert_eq!(font_family,"shareTechMono");},VectorContentRef::Image{key,width,height}=>{kinds.push("image");assert_eq!(text(key),"pixel");assert_eq!((width,height),(10.0,10.0));},VectorContentRef::Group{isolation}=>{kinds.push("group");assert!(isolation)},VectorContentRef::Boolean{operation}=>{kinds.push("boolean");assert_eq!(text(operation),"union");assert_eq!(node.reference_count(),2);assert_eq!(text(node.reference(0).unwrap()),"path");},VectorContentRef::Trace{key,threshold,simplify_epsilon}=>{kinds.push("trace");assert_eq!(text(key),"pixel");assert_eq!((threshold,simplify_epsilon),(0.5,1.0));}}for at in(0..node.child_count()).rev(){pending.push(node.child(at).unwrap());}}assert_eq!(kinds,["group","path","text","shape","image","boolean","trace"]);while !source.terminal_is_empty(){source.close_step(grant()).unwrap();}}
#[test]
fn foreign_native_vector_owner_refuses_with_the_paid_original_metadata_receipt(){let(mut source,_)=RetainedCloneSource::admit_owned(7usize,(),grant()).unwrap_or_else(|_|panic!("actual other native owner"));let error=DRAWING_VECTOR_SOURCE.read(semio_framework_io_ports::erase_child_admission_source(source.borrow(),1),grant()).err().unwrap();assert_eq!(error.retained_progress().copied_bytes,DRAWING_VECTOR_SOURCE.read_demand().copy_bytes);assert_eq!(error.retained_progress().retained_capacity_bytes,0);while !source.terminal_is_empty(){source.close_step(grant()).unwrap();}}
